CREATE OR REPLACE FUNCTION nexus.topics_doc_count_recount_ins() RETURNS TRIGGER LANGUAGE plpgsql SECURITY INVOKER AS $fn$ DECLARE v_tenant_ids TEXT[]; v_topic_ids BIGINT[]; v_i INT; v_bad_tenants TEXT[]; BEGIN -- nexus-4a8pn taxonomy-017: POSTURE TRIPWIRE. See this changeset's own -- header for the full derivation (case (f), measured 2026-09-14 -- the -- cloud's confirmed over-count signature). Under FORCE ROW LEVEL -- SECURITY on nexus.topics, this function's own UPDATE below is -- filtered by the CALLING session's nexus.tenant GUC -- a caller whose -- GUC does not cover every tenant_id this INSERT just landed would -- leave doc_count silently stale. Refuse LOUD instead of recomputing -- wrong. IS DISTINCT FROM (not plain !=) is load-bearing: an entirely -- UNSET GUC makes current_setting(...,true) return NULL, and NULL = -- anything is never TRUE -- IS DISTINCT FROM correctly treats NULL as a -- comparable value, so an unset GUC flags every row as a mismatch too. -- ROLE CHECK (2026-09-14 fix round): a superuser or BYPASSRLS role is -- EXEMPT -- FORCE ROW LEVEL SECURITY never applies to either, so this -- UPDATE cannot be silently filtered for such a role regardless of the -- GUC, and the guard would protect nothing by firing there. Without -- this exemption every test fixture (and any real superuser-driven -- maintenance path) that seeds topic_assignments directly, with no GUC, -- was refused for a hazard that structurally could not apply to it. SELECT array_agg(DISTINCT tenant_id ORDER BY tenant_id) INTO v_bad_tenants FROM new_rows WHERE tenant_id IS DISTINCT FROM current_setting('nexus.tenant', true) AND NOT EXISTS ( SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = current_user AND (rolsuper OR rolbypassrls) ); IF v_bad_tenants IS NOT NULL THEN RAISE EXCEPTION 'topics_doc_count_recount_ins: nexus.tenant GUC (%) does not cover tenant_id(s) % ' 'present in this INSERT on topic_assignments -- under FORCE ROW LEVEL SECURITY on ' 'nexus.topics this trigger''s own UPDATE would be silently filtered to zero rows ' 'for those tenants, leaving doc_count stale (nexus-4a8pn case (f)). Remedy: set ' 'nexus.tenant for the writing session before this statement -- once per tenant if ' 'the batch spans more than one -- or call nexus.topics_recount_doc_count(...) ' 'afterwards to correct it explicitly.', COALESCE(current_setting('nexus.tenant', true), '<unset>'), v_bad_tenants; END IF;
-- Materialize the distinct (tenant_id, topic_id) pairs FIRST, PRE-SORTED -- (ORDER BY inside array_agg itself — deterministic regardless of -- new_rows' own row order), in a statement carrying NO locking clause. SELECT array_agg(tenant_id ORDER BY tenant_id, topic_id), array_agg(topic_id ORDER BY tenant_id, topic_id) INTO v_tenant_ids, v_topic_ids FROM (SELECT DISTINCT tenant_id, topic_id FROM new_rows) d;
-- (1) CORRECTNESS: acquire every affected topics row lock up front, ONE -- ROW AT A TIME via a single-table, PK-indexed, join-free `FOR UPDATE` -- — see the IMPLEMENTATION NOTE above for why a JOIN-based `ORDER BY -- ... FOR UPDATE` does NOT reliably serialize this (PostgreSQL's -- LockRows node locks in JOIN order, not sorted order, once a join is -- involved). Iterating the PRE-SORTED arrays above one indexed -- single-row lock at a time is what actually guarantees every -- concurrent invocation acquires the shared topics in the same -- relative order. FOR v_i IN 1 .. COALESCE(array_length(v_topic_ids, 1), 0) LOOP PERFORM 1 FROM nexus.topics WHERE tenant_id = v_tenant_ids[v_i] AND id = v_topic_ids[v_i] FOR NO KEY UPDATE; END LOOP;
-- (2) PROBABILITY: recompute doc_count for every affected topic via ONE -- batched GROUP BY aggregate (not a per-row correlated subquery -- re-evaluated once per topics row), narrowing the window the -- just-acquired locks above sit held while the scan work happens. UPDATE nexus.topics t SET doc_count = c.cnt FROM ( SELECT ta.tenant_id, ta.topic_id, COUNT(*) AS cnt FROM nexus.topic_assignments ta JOIN (SELECT DISTINCT tenant_id, topic_id FROM new_rows) a ON a.tenant_id = ta.tenant_id AND a.topic_id = ta.topic_id GROUP BY ta.tenant_id, ta.topic_id ) c WHERE t.tenant_id = c.tenant_id AND t.id = c.topic_id; RETURN NULL; END; $fn$;

