CREATE OR REPLACE FUNCTION nexus.topics_doc_count_recount_del() RETURNS TRIGGER LANGUAGE plpgsql SECURITY INVOKER AS $fn$ DECLARE v_tenant_ids TEXT[]; v_topic_ids BIGINT[]; v_i INT; v_bad_tenants TEXT[]; BEGIN -- nexus-4a8pn taxonomy-017: POSTURE TRIPWIRE -- see -- topics_doc_count_recount_ins's identical guard / this changeset's own -- header for the full derivation. A DELETE-driven cascade under CORRECT -- posture (the GUC set to the tenant whose rows are actually being -- deleted) still passes this guard, and its UPDATE below legitimately -- matches zero rows for a topic whose last assignment was just removed -- -- the guard is on POSTURE, never on the UPDATE's row count. ROLE -- CHECK (2026-09-14 fix round): a superuser or BYPASSRLS role is EXEMPT -- -- see the INSERT-path function's identical comment above. SELECT array_agg(DISTINCT tenant_id ORDER BY tenant_id) INTO v_bad_tenants FROM old_rows WHERE tenant_id IS DISTINCT FROM current_setting('nexus.tenant', true) AND NOT EXISTS ( SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = current_user AND (rolsuper OR rolbypassrls) ); IF v_bad_tenants IS NOT NULL THEN RAISE EXCEPTION 'topics_doc_count_recount_del: nexus.tenant GUC (%) does not cover tenant_id(s) % ' 'present in this DELETE on topic_assignments -- under FORCE ROW LEVEL SECURITY on ' 'nexus.topics this trigger''s own UPDATE would be silently filtered to zero rows ' 'for those tenants, leaving doc_count stale (nexus-4a8pn case (f)). Remedy: set ' 'nexus.tenant for the writing session before this statement -- once per tenant if ' 'the batch spans more than one -- or call nexus.topics_recount_doc_count(...) ' 'afterwards to correct it explicitly.', COALESCE(current_setting('nexus.tenant', true), '<unset>'), v_bad_tenants; END IF;
-- Materialize the distinct (tenant_id, topic_id) pairs FIRST, PRE-SORTED -- — same reasoning as the INSERT-path function above. SELECT array_agg(tenant_id ORDER BY tenant_id, topic_id), array_agg(topic_id ORDER BY tenant_id, topic_id) INTO v_tenant_ids, v_topic_ids FROM (SELECT DISTINCT tenant_id, topic_id FROM old_rows) d;
-- (1) CORRECTNESS: same single-row, join-free, PK-indexed lock loop as -- the INSERT-path function above (see its IMPLEMENTATION NOTE). FOR v_i IN 1 .. COALESCE(array_length(v_topic_ids, 1), 0) LOOP PERFORM 1 FROM nexus.topics WHERE tenant_id = v_tenant_ids[v_i] AND id = v_topic_ids[v_i] FOR NO KEY UPDATE; END LOOP;
-- (2) PROBABILITY: single batched-aggregate recompute, LEFT JOINed so a -- topic whose LAST assignment was just deleted (zero remaining rows, -- absent from the aggregate's GROUP BY) still resets to 0 rather than -- being skipped. UPDATE nexus.topics t SET doc_count = COALESCE(c.cnt, 0) FROM (SELECT DISTINCT tenant_id, topic_id FROM old_rows) a LEFT JOIN ( SELECT ta.tenant_id, ta.topic_id, COUNT(*) AS cnt FROM nexus.topic_assignments ta JOIN (SELECT DISTINCT tenant_id, topic_id FROM old_rows) a2 ON a2.tenant_id = ta.tenant_id AND a2.topic_id = ta.topic_id GROUP BY ta.tenant_id, ta.topic_id ) c ON c.tenant_id = a.tenant_id AND c.topic_id = a.topic_id WHERE t.tenant_id = a.tenant_id AND t.id = a.topic_id; RETURN NULL; END; $fn$;

